import cv2
import numpy as np

source_path = 'Downloads/chest-pain-fall-sample.mov'

def open_capture():
    try:
        cap = cv2.VideoCapture(source_path, cv2.CAP_ANY, [cv2.CAP_PROP_HW_ACCELERATION, cv2.VIDEO_ACCELERATION_ANY])
        if cap.isOpened():
            return cap
        cap.release()
    except (cv2.error, AttributeError):
        pass
    cap = cv2.VideoCapture(source_path)
    if not cap.isOpened():
        cap.release()
        raise OSError('Cannot open video: ' + source_path)
    return cap

def bgr_to_nv12(frame):
    height, width = frame.shape[:2]
    if height % 2 or width % 2:
        raise ValueError('NV12 requires even frame dimensions')
    i420 = cv2.cvtColor(frame, cv2.COLOR_BGR2YUV_I420).reshape(-1)
    pixels = height * width
    quarter = pixels // 4
    nv12 = np.empty(pixels + 2 * quarter, dtype=np.uint8)
    nv12[:pixels] = i420[:pixels]
    nv12[pixels::2] = i420[pixels:pixels + quarter]
    nv12[pixels + 1::2] = i420[pixels + quarter:pixels + 2 * quarter]
    return nv12.reshape(height * 3 // 2, width)

def frames():
    cap = open_capture()
    frame_index = 0
    previous_timestamp = None
    try:
        while True:
            ok, frame = cap.read()
            if not ok:
                break
            height, width = frame.shape[:2]
            timestamp = cap.get(cv2.CAP_PROP_POS_MSEC) / 1000.0
            if not np.isfinite(timestamp) or (frame_index > 0 and timestamp <= 0) or (previous_timestamp is not None and timestamp <= previous_timestamp):
                timestamp = frame_index / 24.0
            if previous_timestamp is not None and timestamp <= previous_timestamp:
                timestamp = previous_timestamp + 1.0 / 24.0
            previous_timestamp = timestamp
            metadata = {'camera_id': 'input1', 'timestamp': timestamp, 'frame_index': frame_index, 'width': width, 'height': height}
            yield bgr_to_nv12(frame), metadata
            frame_index += 1
    finally:
        cap.release()

tracks={}; next_id=1

def iou(a,b):
    x1,y1=max(a[0],b[0]),max(a[1],b[1]); x2,y2=min(a[2],b[2]),min(a[3],b[3])
    inter=max(0,x2-x1)*max(0,y2-y1)
    union=max(0,a[2]-a[0])*max(0,a[3]-a[1])+max(0,b[2]-b[0])*max(0,b[3]-b[1])-inter
    return inter/union if union>0 else 0.0

def process(detections, meta):
    global next_id
    available=set(tracks); unmatched=set(range(len(detections))); matched={}
    candidates=sorted(((iou(tracks[tid]['box'],detections[j]['box']),tid,j) for tid in available for j in unmatched),reverse=True)
    for overlap,tid,j in candidates:
        if overlap<parameters['association_iou_threshold']: break
        if tid not in available or j not in unmatched: continue
        matched[j]=tid; available.remove(tid); unmatched.remove(j)
    for tid in available:
        tracks[tid]['missed']+=1
        if tracks[tid]['missed']>parameters['max_missed_frames']: del tracks[tid]
    for j in sorted(unmatched):
        matched[j]=next_id; next_id+=1
    observed=[]
    for j,d in enumerate(detections):
        tid=matched[j]; x1,y1,x2,y2=d['box']
        previous=tracks.get(tid)
        center=((x1+x2)/2,(y1+y2)/2)
        item={**d,'track_id':tid,'center':center,'timestamp':meta['timestamp'],'previous_center':previous['center'] if previous else None,'previous_timestamp':previous['timestamp'] if previous else None,'previous_body_height':previous['body_height'] if previous else None}
        tracks[tid]={'box':d['box'],'center':center,'timestamp':meta['timestamp'],'body_height':max(y2-y1,1e-6),'missed':0}
        observed.append(item)
    return observed
# Retained missed IDs are for association only: output contains current observations, never stale boxes.

import math
states={}

def process(observed, meta):
    now=meta['timestamp']; current_ids={d['track_id'] for d in observed}; transitions=[]; snapshot=[]
    # Missing observations cannot establish continuous visible fallen posture.
    for tid,s in states.items():
        if tid not in current_ids and s['state'] in ('FALL_DETECTED','IMMOBILE_ON_GROUND'):
            s.update(state='UPRIGHT',since=None,last_center=None,last_time=None)
    for d in observed:
        tid=d['track_id']; s=states.setdefault(tid,{'state':'UPRIGHT','since':None,'last_center':None,'last_time':None})
        k=d['keypoints']; x1,y1,x2,y2=d['box']; height=max(y2-y1,1e-6)
        # Torso points follow the model's COCO order: shoulders 5,6 and hips 11,12.
        valid=all(k[i][2]>=0.30 for i in (5,6,11,12))
        angle=None
        if valid:
            shoulder=((k[5][0]+k[6][0])/2,(k[5][1]+k[6][1])/2)
            hip=((k[11][0]+k[12][0])/2,(k[11][1]+k[12][1])/2)
            angle=math.degrees(math.atan2(abs(hip[1]-shoulder[1]),abs(hip[0]-shoulder[0])))
        ratio=(x2-x1)/height
        horizontal=angle is not None and angle<parameters['fall_angle_threshold_deg'] and ratio>parameters['bbox_width_height_ratio_threshold']
        previous=d['previous_center']; previous_time=d['previous_timestamp']
        dt=now-previous_time if previous_time is not None else 0
        body=max(d['previous_body_height'] or height,1e-6)
        descent=(d['center'][1]-previous[1])/body/dt if previous is not None and dt>0 else 0.0
        candidate=horizontal and descent>parameters['downward_descent_velocity_threshold_body']
        if s['state']=='UPRIGHT':
            if candidate: s.update(state='FALL_DETECTED',since=now,last_center=d['center'],last_time=now)
        elif not horizontal:
            # Upright recovery or loss of horizontal posture resets the continuous interval.
            s.update(state='UPRIGHT',since=None,last_center=None,last_time=None)
        elif s['state'] in ('FALL_DETECTED','IMMOBILE_ON_GROUND'):
            elapsed=now-s['last_time'] if s['last_time'] is not None else 0
            speed=math.hypot(d['center'][0]-s['last_center'][0],d['center'][1]-s['last_center'][1])/body/elapsed if elapsed>0 else float('inf')
            if speed>parameters['immobility_center_speed_threshold_body']:
                s.update(state='FALL_DETECTED',since=now,last_center=d['center'],last_time=now)
            else:
                s['state']='IMMOBILE_ON_GROUND'; s['last_center']=d['center']; s['last_time']=now
                duration=now-s['since']
                if duration>=parameters['immobility_persistence_seconds']:
                    s['state']='CONFIRMED_ALARM'
                    transitions.append({'track_id':tid,'camera_id':meta['camera_id'],'timestamp':now,'fall_confidence':d['score'],'floor_duration_sec':duration})
        snapshot.append({'track_id':tid,'state':s['state'],'floor_duration_sec':max(0,now-s['since']) if s['since'] is not None else 0,'torso_angle_deg':angle,'bbox_width_height_ratio':ratio,'descent_body_heights_per_second':descent})
    return {'states':snapshot,'confirmed_transitions':transitions}
# Confidence is the underlying pose-detection score, not a calibrated probability of falling.

def process(fall_result):
    events=[]
    for transition in fall_result['confirmed_transitions']:
        events.append({'camera_id':transition['camera_id'],'timestamp':transition['timestamp'],'fall_confidence':transition['fall_confidence'],'floor_duration_sec':transition['floor_duration_sec'],'track_id':transition['track_id']})
    return {'events':events}
# The upstream FSM produces each transition once; an empty list is emitted on every other frame.

