import cv2, os
EDGES=[(0,1),(0,2),(1,3),(2,4),(5,6),(5,7),(7,9),(6,8),(8,10),(5,11),(6,12),(11,12),(11,13),(13,15),(12,14),(14,16)]
LINE_COLOR=(0,255,0); DOT_COLOR=(0,0,255)
os.makedirs('/alerts/',exist_ok=True)

def process(pixelated_nv12,detections,alert_batch):
    # The only image input is the privacy step's output. Draw the requested skeleton on that image, not an unmasked original.
    if not alert_batch['events']: return None
    frame=cv2.cvtColor(pixelated_nv12,cv2.COLOR_YUV2BGR_NV12)
    for d in detections:
        kp=d['keypoints']
        for a,b in EDGES:
            if kp[a][2]>=0.30 and kp[b][2]>=0.30:
                cv2.line(frame,(int(kp[a][0]),int(kp[a][1])),(int(kp[b][0]),int(kp[b][1])),LINE_COLOR,2,cv2.LINE_AA)
        for x,y,confidence in kp:
            if confidence>=0.30: cv2.circle(frame,(int(x),int(y)),4,DOT_COLOR,-1,cv2.LINE_AA)
    for event in alert_batch['events']:
        stamp=str(event['timestamp']).replace('.','_')
        filename=f"fall_{event['camera_id']}_{stamp}_track{event['track_id']}.png"
        if not cv2.imwrite(os.path.join('/alerts/',filename),frame): raise OSError(filename)
    return None
